function validate([s]) {
  if (typeof s !== 'string' || s.length < 2 || s.length > 100) return 's needs 2 to 100 characters.';
  if (!/^[1-9]+$/.test(s)) return 's may contain only the digits 1 to 9.';
  return null;
}

