function findValidPair(s) {
  const count = new Array(10).fill(0);
  for (const ch of s) {
    count[Number(ch)]++;
  }

  for (let i = 0; i + 1 < s.length; i++) {
    const first = Number(s[i]);
    const second = Number(s[i + 1]);
    if (first === second) {
      continue;
    }
    if (count[first] === first && count[second] === second) {
      return s[i] + s[i + 1];
    }
  }
  return "";
}

