function findValidPair(s) {
  // Recount the whole string for every digit of every pair.
  const occurrences = digit => s.split('').filter(c => c === digit).length;
  for (let i = 0; i < s.length - 1; i++) {
    const a = s[i], b = s[i + 1];
    if (a !== b && occurrences(a) === parseInt(a, 10) && occurrences(b) === parseInt(b, 10)) return a + b;
  }
  return '';
}

