function generate(rand, size) {
  const large = size === 'large';
  const length = large ? 100 : 2 + Math.floor(rand() * 9);
  // A random string seldom holds a digit d exactly d times, so some digits are planted with exactly that count.
  const chars = [];
  const planted = [];
  for (let d = 1; d <= (large ? 9 : 4); d++) {
    if (rand() < 0.5 && chars.length + d <= length) {
      planted.push(d);
      for (let k = 0; k < d; k++) chars.push(String(d));
    }
  }
  // Large inputs fill up with digits that were not planted, so the planted counts stay exact; small ones may break them.
  let pool = [1, 2, 3, 4, 5, 6, 7, 8, 9].filter(d => !large || !planted.includes(d));
  if (!pool.length) pool = [1, 2, 3, 4, 5, 6, 7, 8, 9];
  const spread = large ? pool.length : 1 + Math.floor(rand() * pool.length);
  while (chars.length < length) chars.push(String(pool[Math.floor(rand() * spread)]));
  for (let i = chars.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [chars[i], chars[j]] = [chars[j], chars[i]];
  }
  return [chars.join('')];
}
